#!/usr/bin/env python3
"""
Round 142b (culprits), 2 October 2026. Needs round 141b.

Combine the ticked layers: base map kept, layers clipped to the crossings, outline only.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 142b (2 October)\n\nNeeds round 141b. No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers (asked 2 October: the base map must show for\n  context; a third layer ticked did not update it; lines ran round the\n  southern hemisphere; too slow):\n  - no veil over the map any more: what is not a crossing is taken off the\n    layers themselves. Points by "within" as before; lines and areas drawn\n    again from their own features clipped to the crossings (comboCopies,\n    comboClip: layers <layer>__cut on source <row>__cut, the originals made\n    clear and put back after); pictures clipped pixel by pixel through a new\n    combocut:// protocol (setTiles, put back after). The base map shows\n    everywhere.\n  - every crossing of two or more layers is kept (was only where the most\n    meet), so a third layer adds its crossings; the outline is drawn round\n    the crossings only (comboEdges), pale ice, and brighter and thicker where\n    the most cross. Menu choice renamed "Where they cross".\n  - squares past 85 degrees take no part (pictures covering Antarctica made\n    full-width squares there, drawn as lines round the world).\n  - each run is numbered (COMBO.gen): an older run still reading when a newer\n    one starts is dropped (it had overwritten the newer one: the third layer\n    lost). A run that finds the same crossings from the same rows touches\n    nothing on the map (COMBO.lastKey); first run 400 ms after a tick (was up\n    to 1.8 s).\n- Checked in Chromium (MapLibre 5.24, globe) on a test page with the code:\n  an area cut to the crossing, a picture cleared outside it, the outline and\n  the brighter inner outline drawn, everything put back when turned off. The\n  whole map was not run in a browser.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round142b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 141b" not in h.read_text(encoding="utf-8"):
        sys.exit("round142b: round 141b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round142b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round142b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round142b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ""

if __name__ == "__main__":
    main()
